// 以真实旧经济夹具检验生产管理；不替换钱货、授权或供养规则。
#define main dynamic_economy_fixture_main
#include "../dynamic_economy_test.cpp"
#undef main
#include "resident/domains/local_economy/production_management.hpp"
#include "resident/domains/local_economy/views/local_economy_view.hpp"
// 显式v1只开启既有单元；土地来源和劳力上限均使用作者记录。
void enable_management(Fixture& f,Integer capacity=10){
    f.catalog.production_management=ProductionManagementCatalog{};
    f.catalog.production_management->assets.insert("land",{"land","town","macro.test.land",{Owner::Kind::organization,"city",{}},ProductionAssetKind::land,capacity});
    f.catalog.production_management->plans.insert("farm",{"farm","",{{"land",capacity,1}}});
    f.economy.production_management=ProductionManagementState{};
    f.org_catalog.grants.find("city.grant")->allowed_command_kinds.push_back("configure_local_production");f.validate();
}
// 作者授权的原始配置是恢复上限；操作者仍须通过真实Office/Grant。
ConfigureLocalProductionCommand configure(Integer workers){return {"mayor","farm",ActingAuthority{"city","mayor.office",0,"mayor"},ProductionConfigurationKind::configure,{{"farm.labor",workers}}};}
// 独立探针保留原红：一个只能配置两人的grant不能安排三人。
int limit_probe(){Fixture f;enable_management(f);f.org_catalog.grants.find("city.grant")->amount_limit=2;OrganizationAccess access(f.common,f.organizations,f.org_catalog,f.economy);auto quote=preview_configure_local_production(f.common,f.economy,f.catalog,access,configure(3));if(quote.ok){std::cout<<"EXPECTED_RED production configuration bypassed grant limit: limit=2, workers=3\n";return 9;}std::cout<<"production_limit: PASS (grant limit=2 rejects workers=3)\n";return 0;}
// 上限本身允许，撤权和整数溢出明确拒绝；失败不改变计划或ID。
void limit_boundaries(){Fixture f;enable_management(f);auto* grant=f.org_catalog.grants.find("city.grant");grant->amount_limit=2;OrganizationAccess access(f.common,f.organizations,f.org_catalog,f.economy);assert(preview_configure_local_production(f.common,f.economy,f.catalog,access,configure(2)).ok);const auto before=encode_local_economy_state(f.economy,false,false,true);const auto ids=f.common.state().next_instance_id;auto bad=configure(INT64_MAX);bad.targets.push_back({"second",1});assert(!apply_configure_local_production(f.common,f.economy,f.catalog,access,bad).ok);f.organizations.offices.find("mayor.office")->epoch=1;assert(!apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(2)).ok);assert(ids==f.common.state().next_instance_id&&compare_boundary(before,encode_local_economy_state(f.economy,false,false,true)).exact());}
// 新管理状态不能用旧writer静默丢字段；旧读取布局仍保持原字节合同。
int codec_probe(){Fixture f;enable_management(f);bool boundary_rejected=false;try{encode_local_economy_state(f.economy);}catch(const boundary::DecodeFailure&){boundary_rejected=true;}CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);const auto checkpoint=visit_local_economy_checkpoint(writer,f.economy);if(!boundary_rejected||checkpoint.ok){std::cout<<"EXPECTED_RED old economy writer silently drops management state\n";return 9;}std::cout<<"production_codec: PASS (wrong-profile boundary and checkpoint writers reject)\n";return 0;}
// 下期配置不反算本期，原应付和真实支付在新生产人数下继续存在。
void next_cycle_and_debt(){Fixture f;enable_management(f);OrganizationAccess access(f.common,f.organizations,f.org_catalog,f.economy);const auto common_before=encode_common_state(f.common.state());const auto economy_before=encode_local_economy_state(f.economy,false,false,true);auto quote=preview_configure_local_production(f.common,f.economy,f.catalog,access,configure(3));assert(quote.ok&&quote.value.effective_tick==1&&quote.value.first_due_tick==2);assert(compare_boundary(common_before,encode_common_state(f.common.state())).exact()&&compare_boundary(economy_before,encode_local_economy_state(f.economy,false,false,true)).exact());auto result=apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(3));assert(result.ok&&f.economy.labor_allocations.find("farm.labor")->workers==10);f.validate();f.step(1);assert(f.economy.production_receipts.rows().back().second.batches==10&&f.economy.labor_allocations.find("farm.labor")->workers==3);assert(outstanding_arrears(f.economy,"teacher.salary").value==13);f.validate();f.step(2);assert(f.economy.production_receipts.rows().back().second.batches==3&&f.common.wallet("teacher.wallet")->balance==7);f.validate();}
// 增量预留与其他工作争用同一劳力；取消只释放尚未使用部分，不恢复过去产出。
void reservation_cancel_and_cold(){Fixture f;enable_management(f);OrganizationAccess access(f.common,f.organizations,f.org_catalog,f.economy);assert(apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(0)).ok);f.step(1);assert(f.economy.labor_allocations.find("farm.labor")->workers==0);assert(apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(10)).ok);assert(!allocate_labor(f.common,f.economy,{"other","workers","other_work",1,2,50,"other"}).ok);f.validate();const auto encoded=encode_local_economy_state(f.economy,false,false,true);auto restored=decode_local_economy_state(encoded,false,false,true);assert(restored.ok&&compare_boundary(encoded,encode_local_economy_state(restored.value,false,false,true)).exact());CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto copy=f.economy;assert(visit_local_economy_checkpoint(writer,copy,false,false,true).ok&&writer.finish().ok);LocalEconomyState cold;const auto& input=bytes;CodecVisitor reader(input);assert(visit_local_economy_checkpoint(reader,cold,false,false,true).ok&&reader.finish().ok&&compare_boundary(encoded,encode_local_economy_state(cold,false,false,true)).exact());f.economy=std::move(cold);auto cancelled=configure(0);cancelled.kind=ProductionConfigurationKind::cancel_pending;cancelled.targets.clear();assert(apply_configure_local_production(f.common,f.economy,f.catalog,access,cancelled).ok);assert(f.economy.labor_allocations.find("farm.labor")->workers==0&&f.economy.production_management->pending_by_unit.empty());assert(allocate_labor(f.common,f.economy,{"other","workers","other_work",1,2,50,"other"}).ok);const auto before=encode_local_economy_state(f.economy,false,false,true);const auto ids=f.common.state().next_instance_id;assert(!apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(10)).ok);assert(ids==f.common.state().next_instance_id&&compare_boundary(before,encode_local_economy_state(f.economy,false,false,true)).exact());f.validate();}
// 土地/设施上限和有限季节读取同一配方；篡改冻结来源或重复占用无法通过验证。
void capacity_season_and_corruption(){Fixture f;enable_management(f,6);f.step(1);const auto& receipt=f.economy.production_receipts.rows().back().second;assert(receipt.batches==6&&receipt.production_context&&receipt.production_context->capacity==6);f.validate();auto broken=f.economy;broken.production_receipts.rows().back().second.production_context->capacity=7;assert(!validate_production_management(f.common,broken,f.catalog).ok);auto invalid=f.catalog;invalid.production_management->plans.find("farm")->asset_uses.push_back({"land",1,1});assert(!validate_production_management(f.common,f.economy,invalid).ok);
    Fixture seasonal;enable_management(seasonal);seasonal.catalog.production_management->seasons.insert("year",{"year",0,1,{10000,5000}});seasonal.catalog.production_management->plans.find("farm")->season_profile_id="year";seasonal.step(1);assert(seasonal.economy.production_receipts.rows().back().second.batches==5);seasonal.step(2);assert(seasonal.economy.production_receipts.rows().back().second.batches==10);seasonal.validate();}
// 玩家DTO直接取真实授权、劳力和pending来源；请求事实在后续应用后仍保原观察。
BoundaryValue configuration_page(){Fixture f;enable_management(f);f.common.state().metadata.player_actor_id="mayor";f.org_catalog.grants.find("city.grant")->allowed_command_kinds.push_back("inspect_local_economy");OrganizationAccess access(f.common,f.organizations,f.org_catalog,f.economy);auto requested=apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(3));assert(requested.ok);const auto request_id=requested.value.fact_ids.back();auto original=local_economy_dynamic_fact(f.economy,request_id);assert(original&&original->outcome=="scheduled_for_next_complete_cycle"&&original->rule_version=="production_management_v1");auto index=build_local_economy_index(f.common,f.economy,f.catalog,f.organizations,access);auto page=query_local_economy(f.common,f.economy,f.catalog,access,index,{"mayor","town",ActingAuthority{"city","mayor.office",0,"mayor"},{}});assert(page.ok&&!page.value.rows.empty());const auto* production=std::get_if<LocalProductionView>(&page.value.rows[0]);assert(production&&production->may_configure&&production->labor.size()==1&&production->labor[0].workers==10&&production->labor[0].maximum_workers==10&&production->pending_configuration&&production->pending_configuration->targets[0].workers==3&&production->context&&production->context->capacity==10);auto encoded=encode_local_economy_page(page.value);f.step(1);const auto* resolution=f.economy.production_management->results.rows().empty()?nullptr:&f.economy.production_management->results.rows().back().second;assert(resolution);auto applied=local_economy_dynamic_fact(f.economy,resolution->id);auto still_original=local_economy_dynamic_fact(f.economy,request_id);assert(applied&&applied->outcome=="applied"&&applied->cause_fact_ids==std::vector<StableId>{request_id}&&still_original&&still_original->outcome==original->outcome&&still_original->tick==original->tick);return encoded;}
// 新命令保存和解码保留完整授权与人数；未知字段、标签和错误数值类型必须失败。
void command_boundary(){
    for(auto command:{configure(3),ConfigureLocalProductionCommand{"mayor","farm",{},ProductionConfigurationKind::cancel_pending,{}}}){
        const auto encoded=encode_configure_local_production(command);
        auto decoded=decode_configure_local_production(encoded);
        assert(decoded.ok&&compare_boundary(encoded,encode_configure_local_production(decoded.value)).exact());
        auto unknown=encoded;unknown.as<BoundaryValue::Dict>()->push_back({"balance",BoundaryValue{Integer{100}}});
        assert(!decode_configure_local_production(unknown).ok);
        auto kind=encoded;kind.find("kind")->data=StableId("mint");assert(!decode_configure_local_production(kind).ok);
    }
    auto wrong=encode_configure_local_production(configure(3));
    wrong.find("targets")->as<BoundaryValue::Array>()->front().find("workers")->data=true;
    assert(!decode_configure_local_production(wrong).ok);
}
// NPC/Director原保存点内复用同一业务，失败后的共同fact/ID及经济写集都回到原状态。
void outer_candidate_savepoint(){
    Fixture f;enable_management(f);OrganizationAccess access(f.common,f.organizations,f.org_catalog,f.economy);auto before=encode_common_state(f.common.state());const auto economy_before=encode_local_economy_state(f.economy,false,false,true);auto original=f.economy;auto mark=f.common.begin_savepoint();assert(mark.ok);
    auto nested=apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(3));assert(!nested.ok&&nested.error.original.code=="NestedCommonSavepoint");
    auto changed=apply_configure_local_production_in_candidate(f.common,f.economy,f.catalog,access,configure(3));assert(changed.ok&&!f.economy.production_management->pending_by_unit.empty());assert(f.common.rollback_savepoint(mark.value).ok);f.economy=original;assert(compare_boundary(before,encode_common_state(f.common.state())).exact()&&compare_boundary(economy_before,encode_local_economy_state(f.economy,false,false,true)).exact());
    assert(apply_configure_local_production(f.common,f.economy,f.catalog,access,configure(3)).ok);f.common.state().next_instance_id=INT64_MAX-1;before=encode_common_state(f.common.state());const auto scheduled=encode_local_economy_state(f.economy,false,false,true);mark=f.common.begin_savepoint();assert(mark.ok);auto failed=apply_configure_local_production_in_candidate(f.common,f.economy,f.catalog,access,configure(6));assert(!failed.ok&&failed.error.original.code=="InstanceIdOverflow");assert(f.common.rollback_savepoint(mark.value).ok&&compare_boundary(before,encode_common_state(f.common.state())).exact()&&compare_boundary(scheduled,encode_local_economy_state(f.economy,false,false,true)).exact());
}
int main(int argc,char** argv){outer_candidate_savepoint();command_boundary();if(argc==3&&std::string(argv[1])=="--write-player-page"){auto page=render_boundary_json(configuration_page());assert(page.ok);std::ofstream output(argv[2]);output<<page.value<<"\n";return output?0:1;}if(argc==2&&std::string(argv[1])=="--limit-probe")return limit_probe();if(argc==2&&std::string(argv[1])=="--codec-probe")return codec_probe();configuration_page();limit_boundaries();next_cycle_and_debt();reservation_cancel_and_cold();capacity_season_and_corruption();if(limit_probe()||codec_probe())return 1;std::cout<<"production_management: PASS (next complete cycle, immutable old debt, actual labor reserve/cancel, cold state, land/season sources, rollback)\n";}
